import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../providers/app_providers.dart';

class AdminScreen extends ConsumerStatefulWidget { const AdminScreen({super.key}); @override ConsumerState<AdminScreen> createState()=>_AdminState(); }
class _AdminState extends ConsumerState<AdminScreen> { int tab=0; final tabs=['Користувачі','Класи','Чати','Спільноти','Новини','Модерація','Скарги','Статистика','Журнал подій']; @override Widget build(BuildContext c){final stats=ref.watch(adminStatsProvider);return Scaffold(appBar:AppBar(title:const Text('Адмін-панель')),body:Column(children:[SingleChildScrollView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.all(10),child:Row(children:List.generate(tabs.length,(i)=>Padding(padding:const EdgeInsets.only(right:7),child:ChoiceChip(label:Text(tabs[i]),selected:tab==i,onSelected:(_)=>setState(()=>tab=i)))))),Expanded(child:_body(c,stats))]));}
Widget _body(BuildContext c,Map<String,int> s){if(tab==7)return GridView.count(padding:const EdgeInsets.all(16),crossAxisCount:2,childAspectRatio:1.5,crossAxisSpacing:10,mainAxisSpacing:10,children:s.entries.map((e)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${e.value}',style:const TextStyle(fontSize:28,fontWeight:FontWeight.w800)),Text(e.key)])))).toList());final items=switch(tab){0=>List.generate(18,(i)=>'Користувач №${i+1}'),1=>List.generate(7,(i)=>'${5+i}-А • ${18+i} учнів'),2=>List.generate(12,(i)=>'Чат №${i+1}'),3=>['Шаховий клуб','Робототехніка','Медіацентр'],4=>List.generate(6,(i)=>'Новина №${i+1}'),5=>List.generate(8,(i)=>'Модераційна дія №${i+1}'),6=>List.generate(6,(i)=>'Скарга №${i+1}'),8=>List.generate(25,(i)=>'Подія журналу №${i+1}'),_=>[]};return ListView.builder(padding:const EdgeInsets.all(16),itemCount:items.length,itemBuilder:(c,i)=>Card(child:ListTile(leading:CircleAvatar(child:Text('${i+1}')),title:Text(items[i]),subtitle:const Text('Демонстраційні локальні дані'),trailing:const Icon(Icons.chevron_right))));}}
